+package mirrorrepo
+
+import (
+	"context"
+	"fmt"
+	"time"
+
+	"entire.io/core/model"
+)
+
+// SyncEvidence supplements lifecycle status with proof from a completion.
+// ObservedAt is the completion's immutable JetStream publication timestamp,
+// not the consumer's wall clock: redelivery must not refresh an error's age.
+// FailureCode is bounded vocabulary shared with mirror-pipeline/donejobs;
+// raw errors may contain credentials or regional data and are never persisted.
+type SyncEvidence struct {
+	ObservedAt time.Time
+	Converged bool
+	FailureCode string
+}
+
+// NormalizeSyncFailureCode tolerates older and future workers without storing
+// arbitrary strings in the global control plane. Empty legacy failures and
+// unrecognized codes retain the failure with an explicit unknown reason.
+func NormalizeSyncFailureCode(code string) string {
+	switch code {
+	case "upstream_disabled", "upstream_not_found", "upstream_forbidden",
+		"unauthorized", "resource_limit", "retries_exhausted", "permanent":
+		return code
+	default:
+		return "unknown"
+	}
+}
+
+// RecordSyncEvidence survives failure-index expiry, including on historical
+// ready placements. It never changes lifecycle/election semantics. First
+// verified convergence latches permanently; later failures cannot erase it.
+// Unverified ready/no-op events neither invent success nor clear failures.
+// Missing, suspended, or deleting placements are idempotent no-ops.
+func (s *Service) RecordSyncEvidence(ctx context.Context, id model.RepoID, status string, e SyncEvidence) error {
+	if status != StatusReady && status != StatusFailed {
+		return fmt.Errorf("record mirror sync evidence: unknown status %q", status)
+	}
+	if status == StatusReady && !e.Converged {
+		return nil
+	}
+	if e.ObservedAt.IsZero() {
+		return fmt.Errorf("record mirror sync evidence: missing publication timestamp")
+	}
+	var err error
+	if status == StatusReady {
+		_, err = s.pool.Exec(ctx, `UPDATE mirror_repos
+			SET first_verified_sync_at = LEAST(COALESCE(first_verified_sync_at, $2), $2)
+			WHERE id = $1 AND suspended_at IS NULL AND desired_state = 'active'
+			  AND teardown_started_at IS NULL`, id, e.ObservedAt)
+	} else {
+		_, err = s.pool.Exec(ctx, `UPDATE mirror_repos SET
+			first_sync_failure_at = LEAST(COALESCE(first_sync_failure_at, $2), $2),
+			last_sync_failure_code = CASE
+				WHEN last_sync_failure_at IS NULL OR last_sync_failure_at < $2 THEN $3
+				ELSE last_sync_failure_code END,
+			last_sync_failure_at = GREATEST(COALESCE(last_sync_failure_at, $2), $2)
+			WHERE id = $1 AND suspended_at IS NULL AND desired_state = 'active'
+			  AND teardown_started_at IS NULL`, id, e.ObservedAt, NormalizeSyncFailureCode(e.FailureCode))
+	}
+	if err != nil {
+		return fmt.Errorf("record mirror sync evidence: %w", err)
+	}
+	return nil
+}
+
+// BootstrapState describes evidence, independently of lifecycle status.
+// verified means a convergence was observed, not that the mirror is fresh now.
+func (r ListRow) BootstrapState() string {
+	switch {
+	case r.FirstVerifiedSyncAt != nil:
+		return "verified"
+	case r.FirstSyncFailureAt != nil:
+		return "needs_attention"
+	case r.BootstrapStartedAt != nil:
+		return "pending"
+	default:
+		return "unknown"
+	}
+}
