+package main
+
+import (
+	"errors"
+	"strings"
+
+	gitsync "entire.io/entire/git-sync"
+)
+
+// completionFailureCode records only bounded diagnoses in Core's global
+// placement state. It does not change retry classification. In particular,
+// 404 means unavailable to the current credential, not proof of deletion.
+func completionFailureCode(err error) string {
+	if err == nil {
+		return "unknown"
+	}
+	msg := err.Error()
+	if strings.Contains(msg, "list source refs:") {
+		switch {
+		case strings.Contains(msg, "http 403:") && strings.Contains(msg, "is disabled."):
+			return "upstream_disabled"
+		case strings.Contains(msg, "http 404:"):
+			return "upstream_not_found"
+		case strings.Contains(msg, "http 403:"):
+			return "upstream_forbidden"
+		}
+	}
+	if strings.Contains(msg, "http 401:") || strings.Contains(msg, "sts/token returned 401") || strings.Contains(msg, "sts/token returned 403") {
+		return "unauthorized"
+	}
+	if errors.Is(err, gitsync.ErrCheckpointExceedsTargetLimit) {
+		return "resource_limit"
+	}
+	for _, hint := range permanentPushRejectHints {
+		if strings.Contains(msg, hint) {
+			return "resource_limit"
+		}
+	}
+	if classifyDisposition(err) == dispositionTerm {
+		return "permanent"
+	}
+	return "retries_exhausted"
+}
*** End Patch"));
