package failindex

import (
 "context"
 "errors"
 "fmt"
 "math"
 "strings"
 "time"

 "github.com/nats-io/nats.go"
)

// Tombstone identifies one deleted observation. Revision is a KV stream sequence.
type Tombstone struct {
 Key string
 Revision uint64
}

// Tombstones returns old deletion markers only after the initial scan completes.
func (ix *Index) Tombstones(ctx context.Context, before time.Time) ([]Tombstone, error) {
 w, err := ix.kv.WatchAll(nats.MetaOnly(), nats.Context(ctx))
 if err != nil { return nil, err }
 defer func() { _ = w.Stop() }()
 var result []Tombstone
 for {
  select {
  case <-ctx.Done(): return nil, ctx.Err()
  case e, ok := <-w.Updates():
   if !ok { return nil, errors.New("failindex: incomplete tombstone scan") }
   if e == nil {
    if err := watcherErr(w); err != nil { return nil, err }
    return result, nil
   }
   if (e.Operation() == nats.KeyValueDelete || e.Operation() == nats.KeyValuePurge) && e.Created().Before(before) {
    result = append(result, Tombstone{Key:e.Key(), Revision:e.Revision()})
   }
  }
 }
}

// CompactTombstone purges only messages through the observed deletion marker.
// A later Put has a higher sequence and survives even if it races this call.
// Do not run across a bucket deletion/recreation or stream restore.
func CompactTombstone(ctx context.Context, js nats.JetStreamContext, bucket string, t Tombstone) error {
 if bucket == "" || t.Key == "" || strings.ContainsAny(bucket, ".*> \t\r\n") || strings.ContainsAny(t.Key, "*> \t\r\n") || t.Revision == 0 || t.Revision == math.MaxUint64 {
  return errors.New("failindex: invalid compaction target")
 }
 if err := js.PurgeStream("KV_"+bucket, &nats.StreamPurgeRequest{Subject:"$KV."+bucket+"."+t.Key, Sequence:t.Revision+1}, nats.Context(ctx)); err != nil {
  return fmt.Errorf("failindex: compact %s revision %d: %w", t.Key, t.Revision, err)
 }
 return nil
}
EOF
