package main

import (
 "context"
 "errors"
 "flag"
 "fmt"
 "os"
 "strings"
 "time"

 "github.com/entirehq/mirror-pipeline/pkg/failindex"
)

func runFailindexResolve(ctx context.Context, args []string) error {
 fs := flag.NewFlagSet("failindex resolve", flag.ContinueOnError)
 natsURL, bucket := natsURLFlag(fs), bucketFlag(fs)
 revision := fs.Uint64("revision", 0, "KV revision from failindex get")
 resolution := fs.String("resolution", "", "verified_success or placement_deleted")
 evidence := fs.String("evidence", "", "reference to verified convergence or authoritative placement deletion")
 live := fs.Bool("live", false, "apply the revision-checked resolution")
 ulid, err := parseWithOnePositional(fs, args)
 if err != nil { return helpOrErr(err) }
 if ulid == "" || *revision == 0 || strings.TrimSpace(*evidence) == "" || (*resolution != "verified_success" && *resolution != "placement_deleted") {
  return errors.New("usage: failindex resolve <ulid> --revision N --resolution verified_success|placement_deleted --evidence REF [--live]")
 }
 idx, _, nc, err := openFailIndex(*natsURL, *bucket)
 if err != nil { return err }
 defer nc.Close()
 entry, current, found, err := idx.GetWithRevision(ulid)
 if err != nil { return err }
 if !found || current != *revision { return fmt.Errorf("observation changed: found=%t revision=%d; inspect again", found, current) }
 fmt.Fprintf(os.Stderr, "target: %s revision=%d resolution=%s evidence=%s\n", failIndexRow(ulid, entry), current, *resolution, oneLine(*evidence))
 if !*live { fmt.Fprintln(os.Stderr, "dry-run: no resolution applied"); return nil }
 if err := ctx.Err(); err != nil { return err }
 if err := idx.Resolve(ulid, current); err != nil { return err }
 fmt.Fprintln(os.Stderr, "resolved")
 return nil
}

func runFailindexCompact(ctx context.Context, args []string) error {
 fs := flag.NewFlagSet("failindex compact", flag.ContinueOnError)
 natsURL, bucket := natsURLFlag(fs), bucketFlag(fs)
 age := fs.Duration("older-than", 720*time.Hour, "minimum deletion-marker age")
 limit := fs.Int("limit", 500, "maximum deletion markers to compact")
 live := fs.Bool("live", false, "compact the listed deletion markers")
 if err := fs.Parse(args); err != nil { return helpOrErr(err) }
 if fs.NArg() != 0 || *age <= 0 || *limit <= 0 { return errors.New("compact requires positive --older-than and --limit, and no positional arguments") }
 ctx, cancel := context.WithTimeout(ctx, 5*time.Minute)
 defer cancel()
 idx, js, nc, err := openFailIndex(*natsURL, *bucket)
 if err != nil { return err }
 defer nc.Close()
 markers, err := idx.Tombstones(ctx, time.Now().Add(-*age))
 if err != nil { return err }
 if len(markers) > *limit { markers = markers[:*limit] }
 for _, marker := range markers {
  fmt.Printf("%s\t%d\n", marker.Key, marker.Revision)
  if *live {
   if err := failindex.CompactTombstone(ctx, js, *bucket, marker); err != nil { return err }
  }
 }
 fmt.Fprintf(os.Stderr, "tombstones=%d live=%t\n", len(markers), *live)
 return nil
}
